["loc_chas_intro_01_01"] = "UZUN ZAMAN ÖNCE SHANGHAİ'DA BİRLİKTE İŞ YAPTIĞIM APTAL BİR HERİF BANA BİR ŞEY ÖĞRETMİŞTİ. BELKİ NE ANLAMA GELDİĞİNİ SİZ SÖYLEYEBİLİRSİNİZ DİYE DÜŞÜNDÜM?",
