["loc_chas_intro_02_01"] = "ANLAŞILDI, HERİFLERE HAZIR OLACAĞIZ. O ZAMAN HER ŞEY TAMAM. BAŞKA SÜRPRİZ YOK, DEĞİL Mİ? HARİKA.",
["loc_chas_intro_02_02"] = "GENELDE SİVİL KAYIPLARINDAN KAÇINIRIZ AMA ANLAŞILDI, BİLMEK İYİ OLDU. O İHTİYAR İÇİN KİMSE AĞLAMAZ.",
["loc_chas_intro_03_01"] = "ANLADIĞIM KADARIYLA BİR SÜRE ÖNCE ESKİ ÖĞRENCİM VE BİRKAÇ APTALLA BİRAZ EĞLENMİŞSİNİZ. SİSTEM KIRMAKLA İLGİLİ BİLDİĞİ HER ŞEYİ BEN ÖĞRETTİM, BİLİYOR MUSUNUZ?",
