["loc_chca_021_01"] = "EL İZİNİ ALMANIZ GEREKİYOR, ÇABUK ÇABUK! YANİ ELİNİ ÇABUCAK KESİN DEMİYORUM, SADECE İZİNİ ALIN. GİDİP ALIN DOSTLAR.",
