["loc_chca_079_01"] = "İŞTE BÖYLE YAPILIR, KESİNLİKLE! ŞİMDİ ŞU BOKLARIN BÜTÜN PARASINI SÖMÜRELİM. ÇANTALARI DENİZE ATIN, HEMEN BİRİNİ YOLLAYIP ALDIRIRIM!",
