["loc_chca_080_03"] = "O KASA DAİRESİNDEN ALABİLDİĞİNİZ HER ŞEYİ ÇIKARIN. BU PİSLİKLERİ KESİN İFLASA SÜRÜKLEYECEĞİZ!",
["loc_chca_081_01"] = "YETERİNCE ALDIĞIMIZI DÜŞÜNÜYORSANIZ TRİAD'A KOCAMAN BİR ORTA PARMAK GÖSTERELİM. İŞİNİZ BİTTİYSE KALANINI YAKIN!",
["loc_chca_081_02"] = "YETERİNCE ALDIĞIMIZI DÜŞÜNDÜĞÜNÜZDE KALANINI YAKIN. WANG'A HİÇBİR ŞEY BIRAKMAK İSTEMİYORUZ.",
["loc_chca_081_03"] = "YANINIZA ALMAK İSTEMEDİĞİNİZ HER ŞEYİ YAKIN. TRİAD'IN KULLANACAĞI BİR ŞEY BIRAKMAYA GEREK YOK.",
["loc_chca_082_01"] = "KARAR VERİN. YA KASA DAİRESİ'Nİ BOŞALTIN YA DA KALANI YAKIN.",
["loc_chca_082_02"] = "HADİ DOSTLAR, KALANINI ALIN YA DA YAKIN!",
["loc_chca_082_03"] = "KALANI YAKACAK MISINIZ ALACAK MISINIZ, KARAR VERMELİSİNİZ.",
["loc_chca_083_01"] = "BAZI SERSEMLER PARA YAKMAYI İZLEMEKTEN HOŞLANIR AMA BEN DEĞİL. YİNE DE YUFU WANG ÖĞRENİNCE ÇILDIRACAK, VLAD DA BUNA BAYILACAK!",
["loc_chca_083_02"] = "HEPSİNİ ALAMAMAMIZ YAZIK OLDU AMA EN AZINDAN BÖYLECE TRİAD DA ALAMAYACAK.",
["loc_chca_083_03"] = "BU KADAR BÜYÜK BİR PARA YIĞININI VİCDANINIZ RAHAT BİR ŞEKİLDE YAKMAK HER GÜN NASİP OLMAZ, HA?",
