["loc_chca_119_02"] = "ÜZERİNE BİRAZ YAKIT DÖKÜP YAKIN!",
["loc_chca_119_03"] = "BİR BİDON YAKIT ŞUNU GAYET GÜZEL TUTUŞTURUR!",
["loc_chca_120_01"] = "BENCE O KASAYI XUN KANG AÇABİLİR.",
["loc_chca_120_02"] = "KANG O KASAYI BİR ÇIRPIDA AÇABİLİR, ŞÜPHEM YOK.",
["loc_chca_120_03"] = "KANG'I BUNU BİZE AÇMAYA 'İKNA' ETMEMİZ GEREKEBİLİR.",
["loc_chca_121_01"] = "BENCE XUN KANG O KASAYI AÇABİLİR.",
["loc_chca_121_02"] = "KANG O KASAYI GÖZ AÇIP KAPAYANA KADAR AÇAR, ŞÜPHEM YOK.",
["loc_chca_121_03"] = "KANG'I BİZİM İÇİN AÇMAYA ‘İKNA’ ETMEMİZ GEREKEBİLİR.",
["loc_chca_brf_01"] = "TAMAM HÖDÜKLER, VLAD'IN İNTİKAMINI ALIRKEN BİR BOK YIĞINI PARA KAZANMA VAKTİ. THE BLACK CAT BİRKAÇ SAATE ULUSLARARASI SULARDA OLACAK, İÇİNİ BOŞALTACAĞIZ. JIU FENG'İN İÇERİDE BARMEN OLARAK ÇALIŞAN BİR ADAMI VAR. BİZE EKİPMAN VE GEMİNİN İŞLEYİŞİ HAKKINDA BİLGİ VERECEK. TRİAD ÖZELLİKLE SAVUNMASIZ OLDUĞU İÇİN VLAD'A İŞKENCE EDEN AŞAĞILIK XUN KANG'I GEMİYE KOYDUKLARINI BİLİYORUZ, EN İYİ ADAMLARINDAN BİRİYMİŞ. GEMİDEKİ KUMARHANEYİ Lİ DENG ADLI BİR APTALIN YÖNETTİĞİNİ DE BİLİYORUZ. ANLAŞILAN GÜRÜLTÜCÜ BİR SOYTARIYMIŞ, GOLDEN DAGGER İÇİNDE PEK SAYGI GÖRMÜYORMUŞ. MUHTEMELEN GÜVENLİK YETKİSİNİ PAYLAŞIYORLAR. GEMİYE BİNİNCE İŞİ SIKI TUTMALISINIZ. SAHİL GÜVENLİK BÖLGEDE DEVRİYE GEZİYOR, SİZ ‘BAK, LANET BİR YÜZEN PORSUK!’ DİYEMEDEN ADAMLARINI GEMİYE ÇIKARIRLAR. YANİ SAÇMALAMAK YOK, TAMAM MI?",
["loc_chca_end_loud_01"] = "AFERİN HÖDÜKLER! YUFU WANG VE GOLDEN DAGGER, PAYDAY GANG'İN ADINI DUYDUKLARI GÜNE LANET EDİYOR. ONLARI KESİN YIKIMIN EŞİĞİNE GETİRDİK! ",
["loc_chca_end_stealth_01"] = "İYİ İŞ, DOSTLAR. BU GÜZELDİ. O GOLDEN DAGGER PİSLİKLERİ BİZE BİR DAHA SORUN ÇIKARMADAN ÖNCE KESİNLİKLE İKİ KERE DÜŞÜNECEK!",
["loc_chca_intro_01_01"] = "EEE, KAYINBİRADERİM HAJRUDİN'İ HATIRLIYORSUNUZ, DEĞİL Mİ?",
["loc_chca_intro_01_02"] = "HAYAL MEYAL. NE OLMUŞ ONA?",
["loc_chca_intro_01_03"] = "APTAL OROSPU ÇOCUĞU GEÇEN GÜN FIRINDA YARDIM EDİYORDU. ORADA OTURUP KAHVE İÇEN BİR POLİSLE KONUŞMAYA BAŞLADI, ÇOK APTALCA ŞEYLER SÖYLEDİ. ŞİMDİ BİR ŞEYLER BİLEN O POLİSLE UĞRAŞIYORUM.",
["loc_chca_intro_01_04"] = "BUNUN SOYGUNLA NE İLGİSİ VAR?",
["loc_chca_intro_01_05"] = "BİLMİYORUM! BURADA OTURUP BEKLİYORUZ İŞTE. SADECE SOHBET EDİYORDUM.",
["loc_chca_intro_01_06"] = "TAMAM VLAD... TAMAM.",
["loc_chca_intro_01_07"] = "PEKİ SENCE NE YAPMALIYIM?",
["loc_chca_intro_01_08"] = "BEN NEREDEN BİLEYİM LAN SERSEM!",
["loc_chca_intro_01_09"] = "ONU ÖLDÜRTSEM Mİ, YOKSA İÇİ PARA DOLU KOCAMAN BİR PASTA MI GÖNDERSEM, KARAR VEREMİYORUM. SİZ NE DERSİNİZ?",
["loc_chca_intro_01_10"] = "BUGÜN DE GÜNLERDEN O GÜN OLACAK... ORASI KESİN.",
["loc_chca_intro_02_01"] = "HEY LOCKY! ÇOCUKLARA SÖYLE, BENİ SİKTİĞİMİN ARABA AKÜSÜYLE ÖLDÜRMEYE ÇALIŞAN O ERİŞTE EMİCİ OROSPU ÇOCUĞUNU GÖRÜRLERSE, BURNUNU KESİP GETİRSİNLER!",
["loc_chca_intro_02_02"] = "PARA İÇİN BURADAYIZ SERSEM. BURUN KESMEYE VAKİT YOK.",
["loc_chca_intro_02_03"] = "PEH! HİÇ EĞLENCELİ DEĞİLSİN. BİRAZ DA EĞLENEMEYECEKSEK O KADAR SİKİK PARAYI ÇALMANIN NE ANLAMI VAR, HA?",
["loc_chca_intro_02_04"] = "TAMAM, ŞEY... BELKİ. VAKİT KALIRSA.",
["loc_chca_intro_03_01"] = "EE, BU OROSPU ÇOCUĞUNA TİTANİC'İ YAŞATACAK MIYIZ, NE YAPIYORUZ?",
["loc_chca_intro_03_02"] = "HAYIR SERSEM, GEMİ SİVİLLE DOLU. SADECE PARAYI ALIYORUZ.",
["loc_chca_intro_03_03"] = "ORTALIĞI BİRAZ DAĞITSAK NASIL OLUR?",
["loc_chca_intro_03_04"] = "EH, BENİM EKİBİN İŞİNİN DOĞASINDA BU VAR ZATEN, DEĞİL Mİ?",
["loc_chca_intro_04_01"] = "OROSPU ÇOCUKLARI... AKÜYLE İŞKENCE YAPAN O PİSLİĞİN GEMİDE OLDUĞUNU DUYDUM.",
["loc_chca_intro_04_02"] = "DUYDUĞUMUZ BU, EVET.",
["loc_chca_intro_04_03"] = "ÖLMESİNİ İSTİYORUM. ÖNCE DİZ KAPAKLARINA KURŞUN, SONRA KARNINI YARIP BALIKLARA YEM ETMENİZİ İSTİYORUM.",
["loc_chca_intro_04_04"] = "TAMAMEN ANLAŞILIR. BELKİ FIRSAT ÇIKARSA ÇOCUKLAR HALLEDER.",
["loc_chca_intro_04_05"] = "UMARIM. GERÇEKTEN UMARIM AMINA KOYAYIM. VLAD'A O BOKU YAŞATAN KİMSE SAĞ KALAMAZ. DÜNYA BUNU BİLMELİ! VLAD'IN KORUMASI GEREKEN BİR İTİBARI VAR, BİLİYORSUN.",
["loc_chca_intro_05_01"] = "PEKİ VLAD... HİÇ ÇİNCE BİLİYOR MUSUN?",
["loc_chca_intro_05_02"] = "TEK BİR KELİME BİLE YOK AMINA KOYAYIM.",
["loc_chca_intro_05_03"] = "SİZCE BUNUN ANLAMI NE? ŞU WANG DENEN HERİFE UYUYOR GİBİ: CHİNG-WAH TSAO DUH LİOU MAHNGE.",
["loc_chca_intro_05_04"] = "HER NE DEDİYSE, BENCE DOĞRU SÖYLEMEDİN. HAJRUDİN'İN BİR KERESİNDE İKİ ŞİŞE ROM İÇTİKTEN SONRAKİ HÂLİNE BENZİYORDU.",
["loc_chca_intro_05_05"] = "JIU FENG DE AŞAĞI YUKARI ÖYLE DEDİ.",
["loc_chca_intro_05_06"] = "NE, KAYINBİRADERİMİ Mİ TANIYOR?",
["loc_chca_intro_05_07"] = "HAYIR APTAL, MESELE SÖZÜN TAŞIDIĞI ANLAMDI, TAMAM MI?",
