["loc_des_brf_01"] = "SEVGİLİ DOSTLAR, BU ZORLU BİR İŞ OLACAK. KATARU, BAIN'İN ZIMBIRTISININ PEŞİNE DAHA DA HIRSLA DÜŞTÜ. OYUNCAKLARINI ELLERİNDEN ALMAMIZ GEREKİYOR, HA? VURACAĞIMIZ DEPO, MURKY'NİN EN ÖNEMLİ TESİSİ. ÇOK TUHAF PROJELER ÜZERİNDE ÇALIŞIYORLAR. BENİ ORAYA SADECE BİR KERE YAKLAŞTIRDILAR, PEK BİR ŞEY GÖRMEDİM. YANİ NEYLE KARŞILAŞACAĞIMIZI BİLMİYORUZ. MURKY'DE KALAN BAĞLANTILARIMA SON İYİLİKLERİNE KADAR BAŞVURUP BİR GİRİŞ YOLU AYARLADIM AMA KÖRLEMESİNE GİRECEĞİZ. BUNU YAPINCA DÖNÜŞ OLMAYACAK. RESMEN MURKY'YE AÇIK SAVAŞ İLAN EDİYORUZ AMA BAIN'İN HESABINI O PİÇLERDEN SORMAMIZ LAZIM. DAHA ÖNCE GÖRMEDİĞİMİZ SEVİYEDE GÜVENLİK OLACAK. İÇERİ GİRİNCE İŞE YARAMAZ HÂLE GELMEYİN, TAMAM MI?",
["loc_des_cnc_01"] = "DOSTLAR, ÇÖLDE BİRAZ EĞLENCE İSTER MİSİNİZ? YAĞMALANMASI GEREKEN BİR MURKY TESİSİ VAR.",
["loc_des_cnc_02"] = "MURKYWATER'IN KALBİNE BİR ZİYARET YAPMAYA NE DERSİNİZ?",
["loc_des_cnc_03"] = "MURKYWATER'IN, UZAYLILARIN, ARKEOLOJİNİN, SİLAHLARIN VE KİMYANIN ORTAK NOKTASI NE? ÖĞRENELİM, HA?",
["loc_des_end_01"] = "İYİ İŞ DOSTLAR. ALMAYA GELDİĞİMİZİ ALDIK AMA SONUNCUSU... SONRAKİ HAMLEMİZİ DÜŞÜNMELİYİZ. SİZ DEPODAN AYRILINCA MURKYWATER İLETİŞİMİ TAMAMEN SUSTU, AĞDAN ÇIKTILAR. KATARU'YA İYİ ZARAR VERDİK AMA NASIL MİSİLLEME YAPACAKLARINI BİLMİYORUZ. BAIN, ONA NE OLURSA OLSUN DEVAM ETMEMİZİ İSTERDİ. DUKE BU BULMACANIN SONRAKİ PARÇASINI VE O KUTULARIN ASLINDA NE İŞE YARADIĞINI ÇÖZMEKLE EPEY MEŞGUL OLACAK. O ZAMANA KADAR GİZLENECEĞİZ... PLAN YAPACAĞIZ... HAYATTA KALACAĞIZ.",
["loc_des_intro_01a"] = "BUNU NEDEN YAPTIĞIMIZI BİR DAHA HATIRLATIR MISINIZ?",
["loc_des_intro_01b"] = "SERVET VE ŞAN EVLAT.",
["loc_des_intro_01c"] = "TAMAM. İLKİNİ BEN ALIRIM AMA ŞAN ŞÖHRET SENDE KALABİLİR.",
["loc_des_intro_01d"] = "BELKİ JIMMY HOFFA'YA NE OLDUĞUNU ÖĞRENİRİZ.",
["loc_des_intro_01e"] = "HER ŞEYİ DÜŞÜNÜNCE VEGAS'A DÖNMEYİ TERCİH EDERDİM.",
["loc_des_intro_02a"] = "BU YERDE NE TÜR BOKLAR BULACAĞIZ ACABA?",
