["loc_mex_85_01"] = "DOSTLAR, ŞU BALIKLI TAKOLARIN NEDEN BU KADAR OLAY OLDUĞUNU ANLATMALISINIZ. BANA SORARSANIZ BERBAT GELİYOR. KÖPEKBALIĞI YÜZGECİ OLSA BELKİ...",
["loc_mex_85_02"] = "BİR SEFERİNDE ORMANDA, BİR AVUÇ APTAL TERÖRİSTİN KULLANDIĞI ANTİKA GÜVENLİK SİSTEMİNİ BOKTAN BİR DİZÜSTÜ BİLGİSAYARLA KIRMAYA ÇALIŞIYORDUM. TALİHSİZ BİR ANDA YILAN BACAĞIMI ISIRDI. BEN DE YANLIŞLIKLA ALARMI AÇIP HERKESİ UYARDIM, ONLAR DA BÜTÜN TESİSİ PATLATTI. BİR SÜRÜ TERÖRİST ÖLDÜ, O GÜN KİMSE PARA ALAMADI. LANET YILAN...",
