["loc_mex_cook_11_05"] = "...BİR ŞEYİ KAÇIRMADIYSAM...",
["loc_mex_cook_11_06"] = "...KESİNLİKLE EMİNİM. HERHÂLDE.",
["loc_mex_cook_11_07"] = "...KESİNLİKLE. YA DA BÜYÜK İHTİMALLE.",
["loc_mex_cook_11_08"] = "...EN İYİ TAHMİNİM BU.",
["loc_mex_cook_11_09"] = "...EN İYİ TAHMİNİM BU.",
["loc_mex_cook_11_10"] = "...ÖYLE OLMALI.",
["loc_mex_cook_11_11"] = "...BU BENİM UZMANLIK ALANIM DEĞİL.",
["loc_mex_cook_11_12"] = "...ASLINDA YAŞLI LOCKE'UN EN İYİ YAPTIĞI İŞ BU DEĞİL.",
["loc_mex_cook_11_13"] = "...UMARIM BU İNTERNET SİTESİ DOĞRUDUR.",
["loc_mex_cook_11_14"] = "...OLABİLECEK EN KÖTÜ ŞEY NE, HA?",
["loc_mex_cook_11_15"] = "...ŞU BOKTAN İNTERNET AÇIKLAMALARI PEK ANLAŞILIR DEĞİL.",
["loc_mex_cook_11_16"] = "...TAMAM... TAMAM.",
["loc_mex_cook_11_17"] = "...VE PARMAKLARINIZI ÇAPRAZLAYIN.",
["loc_mex_cook_11_18"] = "...UMARIM İŞE YARAR.",
