["loc_mex_cook_12_03"] = "SANIRIM O DEĞİLDİ.",
["loc_mex_cook_12_04"] = "AH! HAYIR, BU DOĞRU DEĞİLDİ...",
["loc_mex_cook_12_05"] = "BAŞIMIZA BİR SÜRÜ BOK AÇILDI!",
["loc_mex_cook_12_06"] = "EYVAH, MEĞER DOĞRU MALZEME BU DEĞİLMİŞ.",
["loc_mex_cook_12_07"] = "İNTERNETE GÜVENİNCE BÖYLE OLUYOR HERHÂLDE.",
["loc_mex_cook_12_08"] = "LANET OLSUN! OLACAK İŞ Mİ BU?",
["loc_mex_cook_12_09"] = "TAMAM, BU BENİM HATAM.",
["loc_mex_cook_12_10"] = "LOCKE'A HER ZAMAN GÜVENMELİSİNİZ, GÜVENMEMENİZ GEREKEN ZAMANLAR HARİÇ.",
["loc_mex_cook_12_11"] = "HAYIR... BU DOĞRU DEĞİLDİ, DEĞİL Mİ?",
["loc_mex_cook_12_12"] = "BAYAĞI GÜRÜLTÜLÜ, HA?",
["loc_mex_cook_12_13"] = "O BÜYÜK GÜRÜLTÜYÜ DUYDUNUZ MU? DOSTLARIM?",
["loc_mex_cook_12_14"] = "METAMFETAMİN... ECELİNİZ OLMUŞ... KUSURA BAKMAYIN DOSTLAR. KOMİK DEĞİLDİ.",
["loc_mex_cook_12_15"] = "HEH. İNSAN HER GÜN YENİ BİR ŞEY ÖĞRENİYOR GALİBA.",
["loc_mex_cook_12_16"] = "AH, NE KARMAŞA ÇIKARDIK!",
["loc_mex_cook_12_17"] = "AH DOSTUM, BU PEK HOŞ DEĞİLDİ!",
["loc_mex_cook_12_18"] = "İÇİMDEN BİR SES YANLIŞ MALZEME OLDUĞUNU SÖYLEMİŞTİ... DİNLEMELİYDİM!",
["loc_mex_cook_12_19"] = "YANLIŞ MALZEME OLDUĞUNA DAİR İÇİMDE BİR HİS VARDI...",
["loc_mex_cook_12_20"] = "BUNDAN HARİKA BOMBA OLUR...",
["loc_mex_cook_12_21"] = "BELKİ DE BUNLARI KARIŞTIRIYORUM...",
["loc_mex_cook_13_01"] = "BİR PARTİ TAMAM.",
["loc_mex_cook_13_02"] = "PARTİ HAZIR DOSTLAR.",
["loc_mex_cook_13_03"] = "İLK PARTİ HAZIR!",
["loc_mex_cook_14_01"] = "METAMFETAMİNİ YAKINLARDA SAKLAYIN, SONRA BİR PARTİ DAHA PİŞİRELİM.",
["loc_mex_cook_14_02"] = "O PARTİYİ KALDIRIN DA BİRAZ DAHA YAPABİLELİM.",
["loc_mex_cook_14_03"] = "ONU GÜVENLİ BİR YERE GÖTÜRÜN, BİR PİŞİRME ŞÖLENİNE DAHA BAŞLAYALIM.",
["loc_mex_cook_14_04"] = "ONU KALDIRINCA BAŞKA BİR TANE BAŞLATABİLİRSİNİZ.",
["loc_mex_cook_14_05"] = "O PARTİ MALI GÜVENLİ BİR YERE GÖTÜRÜN, ÇABUK ÇABUK. SONRA BİR PARTİ DAHA YAPABİLİRSİNİZ.",
["loc_mex_cook_14_06"] = "ONU YOLDAN ÇEKİP İYİ BİR YERE KOYUN, SONRA İŞE DÖNÜN DOSTLAR.",
["loc_mex_cook_15_01"] = "KAMYONLARDA KULLANABİLECEĞİMİZ MALZEMELER ARAYIN.",
["loc_mex_cook_15_02"] = "MALZEME İÇİN KAMYONLARA BAKIN.",
["loc_mex_cook_15_03"] = "KAMYONLARDA DAHA FAZLA KİMYASAL OLABİLİR.",
["loc_mex_cook_16_01"] = "TAMAM, BU KADARI YETER. PİŞİRMEYE DEVAM EDEBİLİR YA DA ÇIKABİLİRSİNİZ.",
["loc_mex_cook_16_02"] = "HARİKA DOSTLAR. GEREKENİ ALDIK. İSTERSENİZ DAHA FAZLA YAPIN YA DA AYRILIN!",
["loc_mex_cook_16_03"] = "İSTERSENİZ KALIP DAHA FAZLA YAPIN, İSTERSENİZ GİDİN. AMA İHTİYACIMIZ OLANIN HEPSİ ELİMİZDE!",
["loc_mex_cook_17_01"] = "BİR PARTİ DAHA TAMAM!",
["loc_mex_cook_17_02"] = "GÜZEL DOSTLAR. DAHA FAZLA KRİSTAL ALTIN!",
["loc_mex_cook_17_03"] = "BİR TANE DAHA.",
["loc_mex_cook_17_04"] = "APTALLARA DAHA ÇOK YOZLAŞMA!",
["loc_mex_cook_17_05"] = "BİR TANE DAHA...",
["loc_mex_cook_17_06"] = "KAÇ TANE PİŞİRECEKSİNİZ?",
["loc_mex_cook_18_01"] = "BİR YERDE KİLİT ALTINDA DAHA FAZLA MALZEME OLMALI.",
["loc_mex_cook_18_02"] = "HER KÖŞEYE BAKIN, ORADA ÇOK MALZEME OLMASI GEREKİYOR.",
["loc_mex_cook_18_03"] = "ETRAFI İYİCE ARAŞTIRIN, HİÇBİR MALZEMEYİ ATLAMAYIN.",
["loc_mex_cook_19_01"] = "TAMAM, BİR BAKALIM...",
