["loc_mex_cook_22_02"] = "DOĞRU YAPTIYSANIZ ŞİMDİ PİŞECEK!",
["loc_mex_cook_22_03"] = "İŞTE BÖYLE, ŞİMDİ BAŞLAYACAK!",
["loc_mex_cook_22_04"] = "GÜZEL, ŞİMDİ PİŞMESİNİ İZLEYİN!",
["loc_mex_cook_23_01"] = "ELEKTRİK KESİLDİ DOSTLAR, YENİDEN AÇMANIZ LAZIM.",
["loc_mex_cook_23_02"] = "ELEKTRİK KESİLDİ. LÜTFEN GERİ GETİRİN, TAMAM MI?",
["loc_mex_cook_23_03"] = "ELEKTRİK KESİLDİ. GERİ GETİRMENİZ GEREKİYOR.",
["loc_mex_cook_intro_01"] = "BURADA İYİ TARİFLER BULMAYA ÇALIŞIYORUM... BAIN'İN DOSYALARININ BAZILARI FENA KARIŞIK, UMARIM ÇÖZERİM!",
["loc_mex_cook_intro_02"] = "AH, KİMYA DERSİNDE DAHA DİKKATLİ OLMALIYMIŞIM, DEĞİL Mİ? MERAK ETMEYİN DOSTLARIM... YAPA YAPA ÇÖZERİZ.",
["loc_mex_cook_intro_03"] = "TAMAM DOSTLAR. SİZ İŞE KOYULUN, İHTİYAR LOCKE SİZİ KESİN KISA SÜREDE PİŞİRMEYE BAŞLATIR!",
["loc_mex_intro_01"] = "BU İŞTE FENA İNTİKAM ALACAĞIZ GİBİ GELİYOR DOSTLAR.",
["loc_mex_intro_02"] = "BUNDAN SONRA SANGRES'İN HEP BAHSETTİĞİ YERE GİDİP BALIKLI TACO YESEK, BİR DE GÖSTERİ İZLESEK? TWİSTER BİLMEM NEYDİ ADI...",
["loc_mex_intro_03"] = "FAZLA DURMAYIN DOSTLAR. BURASI YARASALAR DİYARI!",
["loc_mex_intro_04"] = "SİLAH DOLU BİR GİTAR ÇANTASI BULURSANIZ... ÖYLECE BIRAKIN, TAMAM MI GERZEKLER?",
["loc_pent_01_01"] = "TAMAM HÖDÜKLER. LOBİDEKİ GÜVENLİĞİ GEÇİP ASANSÖRE ULAŞMANIZ GEREKİYOR. MUHAFIZLAR, KAMERALAR VE METAL DEDEKTÖRLERİ VAR. NE YAPACAĞINIZI BİLİYORSUNUZ, DEĞİL Mİ? HAREKETE GEÇİN.",
["loc_pent_01_02"] = "TAMAM DOSTLAR. ASANSÖRE ULAŞMANIZ GEREKİYOR. KAMERALAR, MUHAFIZLAR VE METAL DEDEKTÖRLERİ VAR. NE YAPACAĞINIZI BİLİYORSUNUZ.",
["loc_pent_01_03"] = "TAMAM. BU LOBİDE MUHAFIZLAR, KAMERALAR VE METAL DEDEKTÖRLERİ VAR. HEPSİNİ GEÇİP ASANSÖRLERİ BULMALISINIZ. HADİ!",
["loc_pent_02_01"] = "BURADA İKİ YOL VAR. SEÇİM SİZİN AMA HAREKETE GEÇİN.",
["loc_pent_02_02"] = "METAL DEDEKTÖRLERİNİN ELEKTRİĞİNİ KESEBİLİR YA DA OFİSTEN GEÇMENİN YOLUNU BULABİLİRSİNİZ.",
["loc_pent_02_03"] = "BURADA İKİ SEÇENEĞİNİZ VAR. BİRİNİ SEÇİN VE HIZLI SEÇİN.",
["loc_pent_03_01"] = "ÜÇ GÜVENLİK KUTUSU VAR. SİSTEME ERİŞEBİLMEM İÇİN DEVRE DIŞI BIRAKIN. YEŞİL IŞIK HANGİSİNDEYSE ŞU AN ONA GİTMENİZ GEREK.",
["loc_pent_03_02"] = "SİSTEME ERİŞMEM İÇİN ÜÇ GÜVENLİK KUTUSUNU DEVRE DIŞI BIRAKMALISINIZ. SIRADA YEŞİL IŞIKLI OLAN VAR, TAMAM MI?",
["loc_pent_03_03"] = "ŞİMDİ ÜÇ GÜVENLİK KUTUSUNU DOĞRU SIRAYLA DEVRE DIŞI BIRAKMALISINIZ. YEŞİL IŞIKLI OLANA GİDİN.",
["loc_pent_04_01"] = "O GÜVENLİK KUTULARINA GİDİN. UNUTMAYIN, YEŞİL IŞIK ETKİN DEMEK, TAMAM MI?",
["loc_pent_04_02"] = "YEŞİL IŞIKLI GÜVENLİK KUTUSUNUN KABLOSUNU KESİN.",
["loc_pent_04_03"] = "YEŞİL IŞIK, ONU KESMENİZ GEREKTİĞİ ANLAMINA GELİYOR.",
["loc_pent_05_01"] = "TAMAM, GÜZEL. GARAJA GİDİP ASANSÖRÜ ÇAĞIRIN. YUKARI ÇIKABİLMENİZ İÇİN BOŞLUĞUN AÇIK OLMASI GEREK.",
["loc_pent_05_02"] = "İYİ İŞ! ŞİMDİ ASANSÖR BOŞLUĞUNU AÇMALISINIZ. GARAJA İNİP ASANSÖRÜ ÇAĞIRIN.",
["loc_pent_05_03"] = "ASANSÖR BOŞLUĞU BOŞ OLMALI. GARAJA GİDİP ASANSÖRÜ ÇAĞIRIN.",
