["loc_pex_intro_02"] = "İÇERİ GİRMELİ, ADAMIMIZI ÇIKARMALI VE HERİFLERİN ALEYHİNE TUTTUĞU BÜTÜN SUÇLAYICI DELİLLERİ YOK ETMELİSİNİZ. ANLAŞILDI MI?",
["loc_quote_set_a"] = "MERHABA. BENİM ADIM LOCKE. MURKYWATER'IN KURDUĞU SİBER GÖREV GÜCÜNÜN BAŞINDAYIM. ÇIKARLARIMIZA YAPTIĞINIZ ONCA SALDIRI YÜZÜNDEN CRIME.NET'İNİZE SIZIP SİZİ YOK ETMEKLE GÖREVLENDİRİLDİK. KUŞKUSUZ ANLADIĞINIZ ÜZERE SIZMA KISMI TAMAMLANDI. ANCAK BU DÜĞMEYE BASARAK SİZİ BİTİRMEK YERİNE BİR TEKLİFLE GELDİM. BENİMLE ÇALIŞMAYA NE DERSİNİZ? SİZE MURKYWATER HAKKINDA İSTİHBARAT, FIRSATLAR VE MALZEME SAĞLAYABİLİRİM. ÜSTELİK SİZİ İŞ ARKADAŞLARIMIN DİKKATİNDEN UZAK TUTABİLİRİM. NE... DERSİNİZ?",
