["loc_rvd_16_02"] = "ORADAN ÇIKINCA NELER OLDUĞUNU DAHA ÇOK KONUŞURUZ. SANIRIM İŞLER ZORLAŞACAK.",
["loc_rvd_brf_01"] = "DOSTLAR! BEN LOCKE. ALASKA'DAN SONRA BANA GÜVENMEK İÇİN PEK SEBEBİNİZ OLMADIĞINI BİLİYORUM AMA SİZİ DC'DEN ÇIKARMAK İÇİN O KISITLI ZAMANDA KURABİLECEĞİMİZ TEK İNANDIRICI OYUN BUYDU. BAIN'İN ESKİDEN GÜVENİLİR SANDIĞI İNSANLAR... BİZİ DİNLİYORDU. ŞİMDİ DE O KAYIP... BİR ŞEY OLACAĞINI BİLİYORDUK AMA NE ZAMAN YA DA NE OLACAĞINI BİLMİYORDUK. SİZİ HABERSİZ BIRAKMA KARARI BAIN'İN DEĞİL, BENİMDİ. GERÇEKTEN ONA ULAŞABİLECEKLERİNİ HİÇ DÜŞÜNMEMİŞTİM. BAKIN, BUNLARI DUYMAK BOKTAN, BİLİYORUM AMA BIRAKTIĞIM SİLAHLARLA ÇIKTINIZ, DEĞİL Mİ? BAIN İÇİN ÜZGÜNÜM... BUNU HALLEDECEĞİZ... AMA ÖNCE SİZİ ORADAN ÇIKARMAMIZ GEREKİYOR. LÜTFEN BANA GÜVENİN MİLLET, SİZİ KANDIRMIYORUM. BUNU KANITLAYACAĞIMA SÖZ VERİYORUM.",
["loc_rvd_end_01"] = "SEVGİLİ DOSTLAR, BANA GÜVENMESENİZ BİLE DİNLEMELİSİNİZ, ÇÜNKÜ İŞLER ÇOK AĞIRLAŞACAK. KISA SÜRE ÖNCE BAIN, PEŞİNDE OLDUĞU KUTSAL KÂSE ZIMBIRTISIYLA İLGİLİ YENİ BİLGİ ALDI. NE OLDUĞUNU SÖYLEMEDİ... ONA İNANMAMAKLA İLGİLİ BİR ŞEY DEDİ AMA ARTIK BAŞKALARININ DA ONU İSTEDİĞİNİ SÖYLEDİ. İŞLERİ DÜZELTMEZSEK CRİMENET DÂHİL BÜTÜN OPERASYON BOKA GİDECEK. ELBETTE PARA İÇİN VARIM AMA BAIN'E BORCUM DA VAR, ÖDEMEYE NİYETLİYİM. ALDSTONE GÜVENLİ EVİN YENİDEN GÜVENLİ OLDUĞUNU SÖYLÜYOR. ORAYA DÖNÜN, HABERLEŞİRİZ. İLGİLENMEM GEREKEN ŞEYLER VAR. BÜYÜK HEDEFİN PEŞİNE DÜŞÜYORUZ... BİR KAYIP RUHU DA GERİ GETİRECEĞİZ.",
["loc_rvd_intro1_01"] = "MİLLET, SİZE BİR KAÇIŞ PLANI BULUP HANGİ CEHENNEMDE NELER DÖNDÜĞÜNÜ ÖĞRENMEYE ÇALIŞACAĞIM, TAMAM MI? DEPO, KISA BİR SOLUKLANMA İÇİN HÂLÂ GÜVENLİ OLMALI.",
